// Item.java
public abstract class Item implements DapatDipinjam {
    private String judul;
    private int stok;

    public Item(String judul, int stok) {
        this.judul = judul;
        this.stok = Math.max(0, stok);
    }

    public String getJudul() {
        return judul;
    }

    public int getStok() {
        return stok;
    }

    @Override
    public boolean tersedia() {
        return stok > 0;
    }

    @Override
    public boolean pinjam() {
        if (stok > 0) {
            stok--;
            return true;
        }
        return false;
    }

    @Override
    public void kembalikan() {
        stok++;
    }

    public abstract int masaPinjamHari();

    public abstract String jenis();

    public String info() {
        return jenis() + ": " + judul + " (stok: " + stok + ")";
    }
}

