// Peminjaman.java
import java.util.ArrayList;
import java.util.List;

public class Peminjaman {
    private Anggota anggota;
    private List<Item> dipinjam = new ArrayList<>();

    public Peminjaman(Anggota anggota) {
        this.anggota = anggota;
    }

    public int getDipinjam() {
        return dipinjam.size();
    }

    public void pinjam(Item item) throws StokHabisException, BatasPinjamException {
        if (dipinjam.size() >= anggota.getBatasPinjam()) {
            throw new BatasPinjamException(anggota.getNama() + " sudah mencapai batas " + anggota.getBatasPinjam() + " item");
        }
        if (!item.pinjam()) {
            throw new StokHabisException("Stok habis: " + item.getJudul());
        }
        dipinjam.add(item);
    }

    public boolean kembalikan(Item item) {
        if (dipinjam.remove(item)) {
            item.kembalikan();
            return true;
        }
        return false;
    }
}

