// Katalog.java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Katalog {
    private List<Item> daftar = new ArrayList<>();

    public void tambah(Item item) {
        daftar.add(item);
    }

    public int jumlah() {
        return daftar.size();
    }

    public List<Item> semua() {
        return new ArrayList<>(daftar);
    }

    public Item cari(String judul) {
        for (Item item : daftar) {
            if (item.getJudul().equalsIgnoreCase(judul)) {
                return item;
            }
        }
        return null;
    }

    public List<Item> urutJudul() {
        List<Item> salinan = new ArrayList<>(daftar);
        Collections.sort(salinan, (a, b) -> a.getJudul().compareToIgnoreCase(b.getJudul()));
        return salinan;
    }

    public List<Item> tersedia() {
        List<Item> hasil = new ArrayList<>();
        for (Item item : daftar) {
            if (item.tersedia()) {
                hasil.add(item);
            }
        }
        return hasil;
    }

    public Map<String, Integer> hitungPerJenis() {
        Map<String, Integer> hitung = new TreeMap<>();
        for (Item item : daftar) {
            hitung.merge(item.jenis(), 1, Integer::sum);
        }
        return hitung;
    }
}

