// Penyimpanan.java
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class Penyimpanan {
    public static void simpan(Katalog katalog, String namaBerkas) throws IOException {
        List<String> baris = new ArrayList<>();
        for (Item item : katalog.semua()) {
            if (item instanceof Buku) {
                Buku b = (Buku) item;
                baris.add("Buku;" + b.getJudul() + ";" + b.getPenulis() + ";" + b.getStok());
            } else if (item instanceof Majalah) {
                Majalah m = (Majalah) item;
                baris.add("Majalah;" + m.getJudul() + ";" + m.getEdisi() + ";" + m.getStok());
            }
        }
        Files.write(Paths.get(namaBerkas), baris);
    }

    public static Katalog muat(String namaBerkas) throws IOException {
        Katalog katalog = new Katalog();
        if (!Files.exists(Paths.get(namaBerkas))) {
            return katalog;
        }
        for (String baris : Files.readAllLines(Paths.get(namaBerkas))) {
            String[] bagian = baris.split(";");
            if (bagian[0].equals("Buku")) {
                katalog.tambah(new Buku(bagian[1], bagian[2], Integer.parseInt(bagian[3])));
            } else if (bagian[0].equals("Majalah")) {
                katalog.tambah(new Majalah(bagian[1], Integer.parseInt(bagian[2]), Integer.parseInt(bagian[3])));
            }
        }
        return katalog;
    }
}

