// ItemFactory.java
public class ItemFactory {
    // keterangan: penulis untuk buku, nomor edisi untuk majalah
    public static Item buat(String jenis, String judul, String keterangan, int stok) {
        if (jenis.equalsIgnoreCase("buku")) {
            return new Buku(judul, keterangan, stok);
        }
        if (jenis.equalsIgnoreCase("majalah")) {
            return new Majalah(judul, Integer.parseInt(keterangan), stok);
        }
        throw new IllegalArgumentException("Jenis tidak dikenal: " + jenis);
    }
}

