import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Katalog katalog = new Katalog();
        katalog.tambah(ItemFactory.buat("buku", "Laskar Pelangi", "Andrea Hirata", 2));
        katalog.tambah(ItemFactory.buat("buku", "Bumi", "Tere Liye", 1));
        katalog.tambah(ItemFactory.buat("majalah", "Tempo", "12", 1));
        Peminjaman peminjaman = new Peminjaman(new Mahasiswa("Sari", "M01"));
        Scanner in = new Scanner(System.in);

        while (true) {
            System.out.println("MENU: 1 pinjam, 2 kembali, 3 daftar, 0 keluar");
            String pilihan = in.nextLine().trim();
            if (pilihan.equals("0")) {
                System.out.println("Terima kasih");
                break;
            } else if (pilihan.equals("1")) {
                Item item = katalog.cari(in.nextLine().trim());
                if (item == null) {
                    System.out.println("Judul tidak ditemukan");
                } else {
                    try {
                        peminjaman.pinjam(item);
                        System.out.println("Dipinjam: " + item.getJudul());
                    } catch (StokHabisException | BatasPinjamException e) {
                        System.out.println(e.getMessage());
                    }
                }
            } else if (pilihan.equals("2")) {
                Item item = katalog.cari(in.nextLine().trim());
                if (item == null) {
                    System.out.println("Judul tidak ditemukan");
                } else if (peminjaman.kembalikan(item)) {
                    System.out.println("Dikembalikan: " + item.getJudul());
                } else {
                    System.out.println("Tidak sedang dipinjam: " + item.getJudul());
                }
            } else if (pilihan.equals("3")) {
                for (Item item : katalog.urutJudul()) {
                    System.out.println(item.info());
                }
            } else {
                System.out.println("Pilihan tidak dikenal");
            }
        }
    }
}

