import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class BukuDao {
    private final String url = "jdbc:sqlite:perpustakaan.db";

    public BukuDao() throws SQLException {
        try (Connection c = DriverManager.getConnection(url); Statement s = c.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS buku (id INTEGER PRIMARY KEY AUTOINCREMENT, judul TEXT, penulis TEXT, stok INTEGER)");
        }
    }

    public void tambah(String judul, String penulis, int stok) throws SQLException {
        try (Connection c = DriverManager.getConnection(url);
             PreparedStatement p = c.prepareStatement("INSERT INTO buku (judul, penulis, stok) VALUES (?, ?, ?)")) {
            p.setString(1, judul);
            p.setString(2, penulis);
            p.setInt(3, stok);
            p.executeUpdate();
        }
    }

    public List<String> daftarJudul() throws SQLException {
        List<String> hasil = new ArrayList<>();
        try (Connection c = DriverManager.getConnection(url);
             Statement s = c.createStatement();
             ResultSet r = s.executeQuery("SELECT judul FROM buku ORDER BY judul")) {
            while (r.next()) {
                hasil.add(r.getString("judul"));
            }
        }
        return hasil;
    }
}

