import javax.swing.*;
import java.awt.BorderLayout;

public class JendelaPerpustakaan {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            Katalog katalog = new Katalog();
            katalog.tambah(ItemFactory.buat("buku", "Bumi", "Tere Liye", 1));
            katalog.tambah(ItemFactory.buat("majalah", "Tempo", "12", 1));

            DefaultListModel<String> model = new DefaultListModel<>();
            JList<String> daftar = new JList<>(model);
            Runnable muatUlang = () -> {
                model.clear();
                for (Item item : katalog.urutJudul()) {
                    model.addElement(item.info());
                }
            };
            muatUlang.run();

            JButton pinjam = new JButton("Pinjam");
            pinjam.addActionListener(e -> {
                int i = daftar.getSelectedIndex();
                if (i >= 0) {
                    katalog.urutJudul().get(i).pinjam();
                    muatUlang.run();
                }
            });

            JFrame jendela = new JFrame("Perpustakaan USG");
            jendela.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            jendela.add(new JScrollPane(daftar), BorderLayout.CENTER);
            jendela.add(pinjam, BorderLayout.SOUTH);
            jendela.setSize(420, 320);
            jendela.setVisible(true);
        });
    }
}
